@staticmethod
def count_handovers(serving):
    """Number of times the serving AP changes to a *different* AP.

    Losing coverage is not itself a handover: ``ap1 -> None -> ap1`` counts
    as zero handovers while ``ap1 -> None -> ap2`` counts as one.
    """
    handovers = 0
    previous = None
    for ap in serving:
        if ap is None:
            continue
        if previous is not None and ap != previous:
            handovers += 1
        previous = ap
    return handovers

