from netsim.net import Mininet
from netsim.topo import RingTopo
from netsim.graph import WeightedGraph

net = Mininet(topo=RingTopo(k=4, n=1, bw=1000, delay=1.0)); net.start()
g = WeightedGraph()
for n in net.nameToNode:
    if n != 'c0': g.add_node(n)
for l in net.links: g.add_edge(l.node1.name, l.node2.name, weight=1)

hosts = [h.name for h in net.hosts]
paths = {}
for s in hosts:
    for d in hosts:
        if s!=d: paths[(s,d)] = g.shortest_path(s,d)
switch = lambda p: [n for n in p if n.startswith('s')]
total = sum(len(switch(p)) for p in paths.values())
print("hosts", hosts, "initial ordered pairs", len(paths), "initial rules", total)
for k,v in sorted(paths.items()): print("  ", k, v)

failed = ('s1','s2')
def uses(p, a, b):
    return any({u,v}=={a,b} for u,v in zip(p,p[1:]))
affected = {k:v for k,v in paths.items() if uses(v,*failed)}
print("affected pairs:", len(affected), sorted(affected))
g.remove_edge(*failed)
reinstalled = 0; detail=[]
for k in sorted(affected):
    np_ = g.shortest_path(*k)
    n = len(switch(np_)) if np_ else 0
    reinstalled += n; detail.append((k, np_, n))
for d in detail: print("  ", d)
print("SDN_LINK_FAILURE_RECOVERY =", reinstalled)
EOF
